for($iteration=0;$iteration -lt 8;++$iteration){[IO.File]::WriteAllText($finalPath,($summary|ConvertTo-Json -Depth 90)+"`n",[Text.UTF8Encoding]::new($false));$cap=R2Capacity;$cap.batch_limit=128MB;$cap.out_limit=3GB;$cap.campaign_limit=8GB;$cap.disk_free_minimum=5GB;$cap.campaign_start_bytes=$before.campaign_plus_prior_bytes;$cap.filesystem_measure='physical file lengths; allocated clusters unknown';$old=$summary.capacity|ConvertTo-Json -Compress;$summary.capacity=$cap;if($old -ceq ($cap|ConvertTo-Json -Compress)){break}}
